    aw_s->countI = countI;
    aw_s->delayI = delayI;
    aw_s->countJ = countJ;
    aw_s->delayJ = delayJ;
    aw_s->countK = countK;
    aw_s->delayK = delayK;
    aw_s->countL = countL;
    aw_s->delayL = delayL;
    aw_s->countM = countM;
    aw_s->delayM = delayM;
    aw_s->countN = countN;
    aw_s->delayN = delayN;
    aw_s->countO = countO;
    aw_s->delayO = delayO;
    aw_s->countP = countP;
    aw_s->delayP = delayP;
